<?php
declare(strict_types=1); require_once __DIR__.'/validation_common.php';
try{[$uid]=currentUser();$method=$_SERVER['REQUEST_METHOD'];$project=trim((string)($_GET['project_id']??''));
 if($method==='GET'){$q=$pdo->prepare("SELECT id,req_key,type,title,acceptance_criteria FROM requirements WHERE project_id=? AND TRIM(COALESCE(acceptance_criteria,''))<>'' ORDER BY FIELD(type,'USR','SYS','SEC','SRS','HRS','SWC','TC'),serial_number,id");$q->execute([$project]);$nodes=[];foreach($q->fetchAll(PDO::FETCH_ASSOC)as$r)foreach(criterionLines((string)$r['acceptance_criteria'])as$i=>$text)$nodes[]=['requirement_id'=>(int)$r['id'],'criterion_index'=>$i,'key'=>$r['req_key'].'#'.($i+1),'req_key'=>$r['req_key'],'type'=>$r['type'],'title'=>$r['title'],'text'=>$text];$q=$pdo->prepare('SELECT * FROM validation_criterion_links WHERE project_id=? ORDER BY id');$q->execute([$project]);$links=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT requirement_id,criterion_index,status,source_run_id,validated_at FROM validation_criterion_states WHERE project_id=?');$q->execute([$project]);$states=$q->fetchAll(PDO::FETCH_ASSOC);$summary=recalculateProjectValidation($pdo,$project);jout(['success'=>true,'nodes'=>$nodes,'links'=>$links,'states'=>$states,'summary'=>$summary]);}
 if($method==='POST'){$x=jbody();$project=trim((string)($x['project_id']??''));$cr=(int)($x['child_requirement_id']??0);$ci=(int)($x['child_criterion_index']??-1);$pr=(int)($x['parent_requirement_id']??0);$pi=(int)($x['parent_criterion_index']??-1);if($cr===$pr&&$ci===$pi)throw new RuntimeException('Ein Kriterium kann nicht mit sich selbst verbunden werden.');if(!criterionExists($pdo,$project,$cr,$ci)||!criterionExists($pdo,$project,$pr,$pi))throw new RuntimeException('Kriterium nicht gefunden.');$q=$pdo->prepare("INSERT INTO validation_criterion_links(project_id,child_requirement_id,child_criterion_index,parent_requirement_id,parent_criterion_index,aggregation_rule,is_required,created_by) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE aggregation_rule=VALUES(aggregation_rule),is_required=VALUES(is_required)");$q->execute([$project,$cr,$ci,$pr,$pi,in_array(($x['aggregation_rule']??'ALL'),['ALL','ANY'],true)?$x['aggregation_rule']:'ALL',!empty($x['is_required'])?1:0,$uid]);$summary=recalculateProjectValidation($pdo,$project);jout(['success'=>true,'summary'=>$summary],201);}
 if($method==='DELETE'){$x=jbody();$id=(int)($x['id']??0);$project=trim((string)($x['project_id']??''));$pdo->prepare('DELETE FROM validation_criterion_links WHERE id=? AND project_id=?')->execute([$id,$project]);$summary=recalculateProjectValidation($pdo,$project);jout(['success'=>true,'summary'=>$summary]);}
 jout(['success'=>false,'error'=>'Methode nicht erlaubt.'],405);
}catch(Throwable$e){jout(['success'=>false,'error'=>$e->getMessage()],400);}
